"""Gate for sim/eval surfaces that are not the default product.

W&B logging, Coval report fields, conversation repair, additional metrics,
tool-call scoring, and engine token reporting stay behind
``FeatureFlag.SIM_EVAL_EXTENDED`` so they can merge without being discoverable
or active on ``main``.
"""

from rasa.utils.feature_flags import FeatureFlag, is_enabled


def extended_eval_enabled() -> bool:
    """Return whether the default-off extended eval surfaces are active."""
    return is_enabled(FeatureFlag.SIM_EVAL_EXTENDED)
